const labels={card:'完整卡面',attack_cg:'局内出招',avatar:'头像',biography:'传记'};let hero='guanyu',tier=0,kind='card',query='',current=0,currentKind='card';const gallery=document.querySelector('#gallery'),viewer=document.querySelector('#viewer');
function button(text,active,fn){const b=document.createElement('button');b.textContent=text;b.className=active?'active':'';b.setAttribute('aria-pressed',active);b.onclick=fn;return b}
function controls(){document.querySelector('#heroes').replaceChildren(...Object.entries({guanyu:'关羽',zhangfei:'张飞',liubei:'刘备'}).map(([h,n])=>button(n,h===hero,()=>{hero=h;tier=0;controls();render()})));const t=document.querySelector('#tiers');t.replaceChildren(...[0,1,2,3,4,5,6].map(n=>button(n?['','一','二','三','四','五','六'][n]+'星':'全部星级',n===tier,()=>{tier=n;controls();render()})));const c=document.querySelector('#categories');c.replaceChildren(...Object.entries(labels).map(([k,v])=>button(v,k===kind,()=>{kind=k;controls();render()})))}
function render(){const forms=FORMS.filter(f=>f.hero===hero&&(!tier||f.tier===tier)&&(!query||f.name.includes(query)));document.querySelector('#eyebrow').textContent=labels[kind];document.querySelector('#sectionTitle').textContent=tier?['','一','二','三','四','五','六'][tier]+'星 · '+(tier>4?'进阶形态':'成长篇章'):'全部形态';document.querySelector('#resultCount').textContent=forms.filter(f=>f.assets[kind]).length+' 份可浏览 / '+forms.length+' 种形态';gallery.className='gallery '+(kind==='biography'?'bio':kind==='avatar'?'avatar':'');gallery.replaceChildren();for(const f of forms){const a=f.assets[kind];if(!a){const el=document.createElement('div');el.className='missing';el.innerHTML=`<span class="number">${String(f.tier).padStart(2,'0')}</span><h3>${f.name}</h3><p>${labels[kind]}尚未制作<br>不使用其他星级素材替代</p>`;gallery.append(el);continue}const el=document.createElement('button');el.className='tile';el.setAttribute('aria-label',f.name+' '+labels[kind]+'，查看大图');el.innerHTML=`<div class="art"><img src="${a.src}" alt="${f.name} ${labels[kind]}" loading="lazy" width="${a.width}" height="${a.height}"></div><div class="meta"><h3>${f.name}</h3><span class="stars">${'★'.repeat(f.tier)}</span></div><div class="sub"><span>${labels[kind]}</span><span class="tag">${a.status==='candidate_pending_review'?'新候选 · 待确认':f.newCard&&kind==='card'?'新合成 · 待确认':'当前审阅版'}</span></div>`;el.onclick=()=>open(FORMS.indexOf(f),kind);gallery.append(el)}if(!forms.length)gallery.innerHTML='<div class="empty">没有找到这个形态，试试“机甲”或“魔关羽”。</div>'}
function open(i,k){current=i;currentKind=k;const f=FORMS[i],a=f.assets[k];document.querySelector('#viewTier').textContent='★'.repeat(f.tier)+'  /  '+labels[k];document.querySelector('#viewTitle').textContent=f.name;const img=document.querySelector('#fullImage');img.src=a.src;img.alt=f.name+' '+labels[k];document.querySelector('#openImage').href=a.src;document.querySelector('#viewTabs').replaceChildren(...Object.keys(labels).filter(v=>f.assets[v]).map(v=>button(labels[v],k===v,()=>open(i,v))));const tx=document.querySelector('#viewText');tx.replaceChildren();const h=document.createElement('h3');h.textContent=k==='biography'&&f.storyTitle?f.storyTitle:labels[k];tx.append(h);const p=document.createElement('p');p.textContent=k==='biography'?(f.story||'当前传记画面，正式文案尚未定稿。'):k==='attack_cg'?(f.move||'局内放招静态美术。技能数值与完整规则不在本页确认范围内。'):k==='avatar'?'角色头像，保留原图完整构图。':'整张卡面包含角色、卡框与卡面信息。'+(f.newCard?' 本张使用现有选定插画与五星模板新合成，待确认。':'');tx.append(p);if(!viewer.open)viewer.showModal();document.body.style.overflow='hidden'}
function navigate(d){const available=FORMS.map((f,i)=>({f,i})).filter(({f})=>f.assets[currentKind]&&f.hero===hero&&(!tier||f.tier===tier)&&(!query||f.name.includes(query)));const idx=available.findIndex(x=>x.i===current);open(available[(idx+d+available.length)%available.length].i,currentKind)}document.querySelector('#prev').onclick=()=>navigate(-1);document.querySelector('#next').onclick=()=>navigate(1);document.querySelector('#close').onclick=()=>viewer.close();viewer.addEventListener('close',()=>document.body.style.overflow='');viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});document.addEventListener('keydown',e=>{if(viewer.open&&e.key==='ArrowLeft')navigate(-1);if(viewer.open&&e.key==='ArrowRight')navigate(1)});document.querySelector('#search').oninput=e=>{query=e.target.value.trim();render()};controls();render();
